const input = $json.body ?? $json;

const errors = [];

const requiredFields = [
  "age",
  "number_of_teeth",
  "number_of_missing_teeth",
  "is_primary_teeth",
  "smoking_status",
  "alcohol_usage",
  "sugar_usage",
  "brushing_frequency",
  "diabetes_status",
  "pregnancy_status",
  "gum_bleeding",
  "tooth_sensitivity",
  "calcium_or_vitamin_deficiency",
  "number_of_filled_teeth",
  "overall_oral_hygiene_level",
  "identified_disease",
  "disease_severity_from_xray",
  "affected_teeth_count",
  "preferred_language"
];

for (const field of requiredFields) {
  if (input[field] === undefined || input[field] === null || input[field] === "") {
    errors.push(`${field} is required`);
  }
}

const allowedRiskValues = ["no", "medium", "high"];
const allowedHygiene = ["good", "moderate", "poor"];
const allowedDisease = ["dental_cavity", "periodontal_bone_loss"];
const allowedSeverity = ["mild", "moderate", "severe"];
const allowedLanguages = ["en", "si", "ta", "hi"];

function isBoolean(value) {
  return typeof value === "boolean";
}

function isInteger(value) {
  return Number.isInteger(value);
}

if (!isInteger(input.age) || input.age < 1 || input.age > 120) {
  errors.push("age must be an integer between 1 and 120");
}

if (!isInteger(input.number_of_teeth) || input.number_of_teeth < 0 || input.number_of_teeth > 32) {
  errors.push("number_of_teeth must be an integer between 0 and 32");
}

if (!isInteger(input.number_of_missing_teeth) || input.number_of_missing_teeth < 0 || input.number_of_missing_teeth > 32) {
  errors.push("number_of_missing_teeth must be an integer between 0 and 32");
}

if ((input.number_of_teeth + input.number_of_missing_teeth) > 32) {
  errors.push("number_of_teeth + number_of_missing_teeth must be less than or equal to 32");
}

if (!isInteger(input.brushing_frequency) || ![0, 1, 2].includes(input.brushing_frequency)) {
  errors.push("brushing_frequency must be 0, 1, or 2");
}

if (!isInteger(input.number_of_filled_teeth) || input.number_of_filled_teeth < 0 || input.number_of_filled_teeth > 32) {
  errors.push("number_of_filled_teeth must be an integer between 0 and 32");
}

if (input.number_of_filled_teeth > input.number_of_teeth) {
  errors.push("number_of_filled_teeth must be less than or equal to number_of_teeth");
}

if (!isInteger(input.affected_teeth_count) || input.affected_teeth_count < 0 || input.affected_teeth_count > 32) {
  errors.push("affected_teeth_count must be an integer between 0 and 32");
}

if (input.affected_teeth_count > input.number_of_teeth) {
  errors.push("affected_teeth_count must be less than or equal to number_of_teeth");
}

for (const field of [
  "is_primary_teeth",
  "diabetes_status",
  "pregnancy_status",
  "gum_bleeding",
  "tooth_sensitivity",
  "calcium_or_vitamin_deficiency"
]) {
  if (!isBoolean(input[field])) {
    errors.push(`${field} must be boolean true or false`);
  }
}

for (const field of ["smoking_status", "alcohol_usage", "sugar_usage"]) {
  if (!allowedRiskValues.includes(String(input[field]).toLowerCase())) {
    errors.push(`${field} must be one of: no, medium, high`);
  }
}

if (!allowedHygiene.includes(String(input.overall_oral_hygiene_level).toLowerCase())) {
  errors.push("overall_oral_hygiene_level must be one of: good, moderate, poor");
}

if (!allowedDisease.includes(String(input.identified_disease).toLowerCase())) {
  errors.push("identified_disease must be dental_cavity or periodontal_bone_loss");
}

if (!allowedSeverity.includes(String(input.disease_severity_from_xray).toLowerCase())) {
  errors.push("disease_severity_from_xray must be mild, moderate, or severe");
}

if (!allowedLanguages.includes(String(input.preferred_language).toLowerCase())) {
  errors.push("preferred_language must be one of: en, si, ta, hi");
}

if (errors.length > 0) {
  return [
    {
      json: {
        valid: false,
        errors,
        received_body: input
      }
    }
  ];
}

return [
  {
    json: {
      valid: true,
      health_profile: {
        ...input,
        smoking_status: String(input.smoking_status).toLowerCase(),
        alcohol_usage: String(input.alcohol_usage).toLowerCase(),
        sugar_usage: String(input.sugar_usage).toLowerCase(),
        overall_oral_hygiene_level: String(input.overall_oral_hygiene_level).toLowerCase(),
        identified_disease: String(input.identified_disease).toLowerCase(),
        disease_severity_from_xray: String(input.disease_severity_from_xray).toLowerCase(),
        preferred_language: String(input.preferred_language).toLowerCase()
      }
    }
  }
];

const profile = $json.health_profile;

function normalizeText(value) {
  return String(value).trim().toLowerCase();
}

function normalizeRiskValue(value) {
  const v = normalizeText(value);

  if (["no", "none", "false", "0", "never"].includes(v)) return "no";
  if (["medium", "moderate", "yes", "true", "1", "occasional"].includes(v)) return "medium";
  if (["high", "heavy", "frequent"].includes(v)) return "high";

  return v;
}

function normalizeBoolean(value) {
  if (typeof value === "boolean") return value;

  const v = normalizeText(value);

  if (["true", "yes", "1"].includes(v)) return true;
  if (["false", "no", "0"].includes(v)) return false;

  return Boolean(value);
}

function normalizeDisease(value) {
  const v = normalizeText(value);

  if (["dental cavity", "cavity", "caries", "dental_caries"].includes(v)) {
    return "dental_cavity";
  }

  if (["periodontal bone loss", "periodontal", "gum disease", "bone_loss"].includes(v)) {
    return "periodontal_bone_loss";
  }

  return v;
}

const normalized = {
  age: Number(profile.age),
  number_of_teeth: Number(profile.number_of_teeth),
  number_of_missing_teeth: Number(profile.number_of_missing_teeth),
  is_primary_teeth: normalizeBoolean(profile.is_primary_teeth),

  smoking_status: normalizeRiskValue(profile.smoking_status),
  alcohol_usage: normalizeRiskValue(profile.alcohol_usage),
  sugar_usage: normalizeRiskValue(profile.sugar_usage),

  brushing_frequency: Number(profile.brushing_frequency),

  diabetes_status: normalizeBoolean(profile.diabetes_status),
  pregnancy_status: normalizeBoolean(profile.pregnancy_status),
  gum_bleeding: normalizeBoolean(profile.gum_bleeding),
  tooth_sensitivity: normalizeBoolean(profile.tooth_sensitivity),
  calcium_or_vitamin_deficiency: normalizeBoolean(profile.calcium_or_vitamin_deficiency),

  number_of_filled_teeth: Number(profile.number_of_filled_teeth),
  overall_oral_hygiene_level: normalizeText(profile.overall_oral_hygiene_level),

  identified_disease: normalizeDisease(profile.identified_disease),
  disease_severity_from_xray: normalizeText(profile.disease_severity_from_xray),

  affected_teeth_count: Number(profile.affected_teeth_count),
  preferred_language: normalizeText(profile.preferred_language)
};

return [
  {
    json: {
      health_profile: normalized
    }
  }
];

const response = $json;

const errors = [];

// Handle HTTP request failure
if (response.error) {
  errors.push(`FastAPI request failed: ${response.error.message || "Unknown error"}`);
}

// Validate required top-level fields
if (response.risk_score === undefined || response.risk_score === null) {
  errors.push("Missing risk_score");
}

if (!response.risk_level) {
  errors.push("Missing risk_level");
}

if (!response.care_plan || typeof response.care_plan !== "object") {
  errors.push("Missing or invalid care_plan");
}

// Validate risk level values
const allowedRiskLevels = ["low", "medium", "high"];

if (
  response.risk_level &&
  !allowedRiskLevels.includes(String(response.risk_level).toLowerCase())
) {
  errors.push("Invalid risk_level value");
}

// Validate risk score range
if (
  typeof response.risk_score === "number" &&
  (response.risk_score < 0 || response.risk_score > 100)
) {
  errors.push("risk_score must be between 0 and 100");
}

// Required care plan keys
const requiredCarePlanKeys = [
  "toothpaste_type",
  "mouthwash_type",
  "interdental_tool",
  "rinse_type",
  "pain_relief",
  "dietary_action",
  "dentist_urgency",
  "monitoring_focus",
  "lifestyle_action"
];

if (response.care_plan) {
  for (const key of requiredCarePlanKeys) {
    if (
      response.care_plan[key] === undefined ||
      response.care_plan[key] === null
    ) {
      errors.push(`Missing care_plan.${key}`);
    }
  }
}

// Return result
if (errors.length > 0) {
  return [
    {
      json: {
        valid_prediction: false,
        prediction_errors: errors,
        raw_response: response
      }
    }
  ];
}

return [
  {
    json: {
      valid_prediction: true,
      model_output: response
    }
  }
];

const profile = $('Normalize Health Profile Values').first().json.health_profile;
const modelOutput = $json.model_output;

return [
  {
    json: {
      ai_context: {
        preferred_language: profile.preferred_language || "en",
        health_profile: profile,
        model_output: modelOutput
      }
    }
  }
];

const raw =
  $json.content ||
  $json.text ||
  $json.message ||
  $json.output;

let parsed;

try {
  parsed = typeof raw === 'string'
    ? JSON.parse(raw)
    : raw;
} catch (e) {
  return [
    {
      json: {
        success: false,
        parse_error: true,
        raw_response: raw,
        error_message: e.message
      }
    }
  ];
}

return [
  {
    json: {
      success: true,
      ai_report: parsed
    }
  }
];

const aiReport = $json.ai_report;

return [
  {
    json: {
      success: true,
      workflow_version: "v1.0",
      generated_at: new Date().toISOString(),
      report: aiReport
    }
  }
];
